/** Legal links are the same across every Omni product (omni.dev catalog SSOT). */
const DEFAULT_LEGAL = {
  privacy: "https://omni.dev/legal/privacy",
  terms: "https://omni.dev/legal/terms",
  cookies: "https://omni.dev/legal/cookies",
};

const FooterLink = ({ className, ...rest }: ComponentProps<"a">) => (
  <a
    target="_blank"
    rel="noreferrer noopener"
    className={cn(
      "rounded px-2 py-1 text-sm transition-colors hover:text-foreground",
      className,
    )}
    {...rest}
  />
);

const Divider = () => (
  <div
    className="bg-muted-foreground/30 hidden h-1/2 w-px sm:block"
    aria-hidden="true"
  />
);

interface AppFooterProps extends ComponentProps<"footer"> {
  /**
   * The product's own logomark (inline SVG or icon element). Optional: many apps
   * brand with a lucide icon or none - omit it and the credit still leads with
   * the product symbol.
   */
  appLogo?: ReactNode;
  /**
   * The product's symbol from the Omni product catalog (`products.ts` `icon`,
   * e.g. Fractal "🔷", Kiln "🔥"), shown in the "Made with <symbol> by Omni"
   * credit. Mirror the catalog value; do not invent one.
   */
  appSymbol: string;
  /** Product docs link. Omit to hide the Docs entry. */
  docsUrl?: string;
  /**
   * App-specific nav links (e.g. Feedback, Status, Blog), rendered next to Docs.
   * Pass the app's own link elements. Keeps adoption from dropping working links
   * the standard slots don't cover.
   */
  links?: ReactNode;
  /**
   * The product's own social links block (apps render their own brand icons).
   * Omit to hide. Always include Threads (`@omnidotdev`) - the commonly missed one.
   */
  socials?: ReactNode;
  /** Org credited in "by <org>". Defaults to Omni / omni.dev. */
  orgName?: string;
  orgUrl?: string;
  /** Legal link overrides; defaults to the omni.dev/legal SSOT. */
  legal?: Partial<typeof DEFAULT_LEGAL>;
}

/**
 * Standard Omni product footer. Bakes in the parts every Omni app must carry -
 * the "Made with <symbol> by Omni" credit, the Omni mark, the omni.dev link, and
 * the legal links - so they cannot drift or be forgotten. Each app supplies only
 * its own identity: `appLogo`, its catalog `appSymbol`, `docsUrl`, and a
 * `socials` block. The branding is one condensed credit line (app logo,
 * copyright, then "Made with <symbol> by Omni"), never two separate blocks.
 */
const AppFooter = ({
  appLogo,
  appSymbol,
  docsUrl,
  links,
  socials,
  orgName = "Omni",
  orgUrl = "https://omni.dev",
  legal,
  className,
  ...rest
}: AppFooterProps) => {
  const legalLinks = { ...DEFAULT_LEGAL, ...legal };

  return (
    <footer
      className={cn(
        "flex w-full flex-col items-center justify-center gap-2 p-4 text-muted-foreground sm:flex-row sm:gap-1",
        className,
      )}
      {...rest}
    >
      <p className="flex flex-wrap items-center justify-center gap-x-1.5 gap-y-1 px-3 text-sm">
        {appLogo}
        <span>&copy; {new Date().getFullYear()}</span>
        <span aria-hidden="true">&middot;</span>
        <span className="flex items-center gap-1.5">
          Made with
          <span aria-hidden="true">{appSymbol}</span>
          by
          <FooterLink
            href={orgUrl}
            className="inline-flex items-center gap-1 px-0"
          >
            <OmniLogo className="size-4" />
            {orgName}
          </FooterLink>
        </span>
      </p>

      {/* Docs, legal, and socials: on mobile they flow into a single centered,
          wrapping row so Docs/Privacy/Terms/Cookies align together instead of
          stacking into separate rows; on sm+ this wrapper is `contents`, so the
          groups and dividers lay out as the original single row. */}
      <div className="flex flex-wrap items-center justify-center gap-x-1 gap-y-1 sm:contents">
        {(docsUrl || links) && (
          <>
            <Divider />
            <div className="flex items-center gap-1">
              {docsUrl && <FooterLink href={docsUrl}>Docs</FooterLink>}
              {links}
            </div>
          </>
        )}

        <Divider />
        <div className="flex items-center gap-1">
          <FooterLink href={legalLinks.privacy}>Privacy</FooterLink>
          <FooterLink href={legalLinks.terms}>Terms</FooterLink>
          <FooterLink href={legalLinks.cookies}>Cookies</FooterLink>
        </div>

        {socials && (
          <>
            <Divider />
            <div className="flex items-center gap-1">{socials}</div>
          </>
        )}
      </div>
    </footer>
  );
};

export { AppFooter };

import { clsx } from "clsx";
import { twMerge } from "tailwind-merge";

import type { ClassValue } from "clsx";

export const cn = (...inputs: ClassValue[]) => {
  return twMerge(clsx(inputs));
};
